#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>

int main(int argc, char *argv[]) {
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2, *end3;
    long long base = strtoll(argv[1], &end1, 10);
    long long exp  = strtoll(argv[2], &end2, 10);
    long long mod  = strtoll(argv[3], &end3, 10);
    if (end1 != argv[1] || end2 != argv[2] || end3 != argv[3]) {
        puts("BAD_INPUT");
        return 0;
    }
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }
    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // fast modular exponentiation using 128-bit intermediate to avoid overflow
    long long result = 1 % mod;
    long long b = base % mod;
    while (exp > 0) {
        if (exp & 1LL) {
            result = (long long)((__int128)result * b % mod);
        }
        b = (long long)((__int128)b * b % mod);
        exp >>= 1;
    }
    printf("result=%lld\n", result);
    return 0;
}
